import { type Clock, MINUTE } from "../util/time.js";
import { isExpired, type Session, type SessionStore, verifySession } from "./session.js";

export interface RateLimitConfig {
	/** Hits allowed per window. */
	limit: number;
	windowMs: number;
}

export interface RateLimitDecision {
	allowed: boolean;
	remaining: number;
	/** How long until the window resets. Zero when allowed. */
	retryAfterMs: number;
}

export interface RateLimiter {
	/** Counts one hit for `key` and says whether it was within the limit. */
	hit(key: string, at: number): RateLimitDecision;
	/** Says whether `key` is currently over the limit, without counting anything. */
	peek(key: string, at: number): RateLimitDecision;
	reset(key: string): void;
}

export const DEFAULT_LOGIN_LIMIT: RateLimitConfig = { limit: 5, windowMs: 15 * MINUTE };

interface Window {
	startedAt: number;
	hits: number;
}

/** A fixed-window limiter: at most `limit` hits per `windowMs`, counted per key. */
export function createRateLimiter(config: RateLimitConfig = DEFAULT_LOGIN_LIMIT): RateLimiter {
	const windows = new Map<string, Window>();

	function current(key: string, at: number): Window {
		const existing = windows.get(key);
		if (existing !== undefined && at - existing.startedAt < config.windowMs) {
			return existing;
		}
		return { startedAt: at, hits: 0 };
	}

	function retryAfter(window: Window, at: number): number {
		return window.startedAt + config.windowMs - at;
	}

	return {
		hit(key, at) {
			const window = current(key, at);
			window.hits += 1;
			windows.set(key, window);
			const allowed = window.hits <= config.limit;
			return { allowed, remaining: Math.max(0, config.limit - window.hits), retryAfterMs: allowed ? 0 : retryAfter(window, at) };
		},
		peek(key, at) {
			const window = current(key, at);
			// Blocked once the limit is used up: one more hit would go over.
			const allowed = window.hits < config.limit;
			return { allowed, remaining: Math.max(0, config.limit - window.hits), retryAfterMs: allowed ? 0 : retryAfter(window, at) };
		},
		reset(key) {
			windows.delete(key);
		},
	};
}

export interface GuardDeps {
	sessions: SessionStore;
	limiter: RateLimiter;
	now: Clock;
}

export type GuardResult = { allowed: true; session: Session | null } | { allowed: false; retryAfterMs: number };

/**
 * Decides whether a request from `clientKey` may proceed. A client that is over its limit is
 * turned away before the session is even looked at.
 */
export function guardRequest(clientKey: string, token: string | undefined, deps: GuardDeps): GuardResult {
	const standing = deps.limiter.peek(clientKey, deps.now());
	if (!standing.allowed) {
		return { allowed: false, retryAfterMs: standing.retryAfterMs };
	}
	const session = verifySession(token, deps.sessions, deps.now);
	if (session === null && token !== undefined) {
		// verifySession reports an expired session as null, so check the stored session ourselves.
		const stored = deps.sessions.get(token);
		if (stored !== undefined && isExpired(stored, deps.now)) {
			deps.limiter.hit(clientKey, deps.now());
		}
	}
	return { allowed: true, session };
}

import * as assert from "../premise/assert.js";
import type { Tests } from "../premise/assert.js";
import { createRateLimiter, guardRequest } from "../src/auth/rate-limit.js";
import { createMemorySessionStore } from "../src/store/memory-store.js";
import { MINUTE } from "../src/util/time.js";
import { makeSession, now, T0 } from "./support.js";

function deps() {
	return {
		sessions: createMemorySessionStore([makeSession(), makeSession({ id: "ses_000002", expiresAt: T0 - 1 })]),
		limiter: createRateLimiter({ limit: 3, windowMs: 10 * MINUTE }),
		now,
	};
}

export const tests: Tests = {
	"requests with an expired session count against the limit": () => {
		const d = deps();
		for (let i = 0; i < 3; i++) {
			assert.deepEq(guardRequest("client-1", "ses_000002", d), { allowed: true, session: null });
		}
		assert.deepEq(guardRequest("client-1", "ses_000002", d), { allowed: false, retryAfterMs: 10 * MINUTE });
	},
	"valid sessions are not counted": () => {
		const d = deps();
		for (let i = 0; i < 10; i++) {
			assert.eq(guardRequest("client-1", "ses_000001", d).allowed, true);
		}
	},
	"anonymous and unknown tokens are not counted": () => {
		const d = deps();
		for (let i = 0; i < 10; i++) {
			assert.eq(guardRequest("client-1", undefined, d).allowed, true);
			assert.eq(guardRequest("client-1", "ses_424242", d).allowed, true);
		}
	},
};
